function generateDeepLink(platform, meetingLink, meetingTitle) {
  const title = meetingTitle || "NeuraTalk Meeting";
  switch (platform) {
    case "google-meet":
      return {
        url: "https://meet.google.com/new",
        type: "create"
      };
    case "microsoft-teams":
      return {
        url: `https://teams.microsoft.com/l/meeting/new?subject=${encodeURIComponent(title)}`,
        type: "create"
      };
    case "zoom":
      return {
        url: "https://zoom.us/start/videomeeting",
        type: "create"
      };
    case "whatsapp": {
      const shareText = meetingLink ? `Join my ${title}: ${meetingLink}` : `Join my ${title} on NeuraTalk`;
      return {
        url: `https://wa.me/?text=${encodeURIComponent(shareText)}`,
        type: "share"
      };
    }
    default:
      throw new Error(`Unsupported platform: ${platform}`);
  }
}
