function createWavHeader(dataSize, sampleRate, bitsPerSample, channels) {
  const header = Buffer.alloc(44);
  const byteRate = sampleRate * channels * (bitsPerSample / 8);
  const blockAlign = channels * (bitsPerSample / 8);
  header.write("RIFF", 0);
  header.writeUInt32LE(36 + dataSize, 4);
  header.write("WAVE", 8);
  header.write("fmt ", 12);
  header.writeUInt32LE(16, 16);
  header.writeUInt16LE(1, 20);
  header.writeUInt16LE(channels, 22);
  header.writeUInt32LE(sampleRate, 24);
  header.writeUInt32LE(byteRate, 28);
  header.writeUInt16LE(blockAlign, 32);
  header.writeUInt16LE(bitsPerSample, 34);
  header.write("data", 36);
  header.writeUInt32LE(dataSize, 40);
  return header;
}
function analyzeAudioPitch(audioBuffer) {
  const samples = [];
  const headerOffset = 44;
  for (let i = headerOffset; i < audioBuffer.length - 1; i += 2) {
    if (i + 1 < audioBuffer.length) {
      samples.push(audioBuffer.readInt16LE(i));
    }
  }
  if (samples.length < 1600) {
    return { estimatedGender: "male", fundamentalFrequency: 120, confidence: 0.3 };
  }
  const sampleRate = 16e3;
  const minPeriod = Math.floor(sampleRate / 400);
  const maxPeriod = Math.floor(sampleRate / 60);
  const frameSize = Math.min(4096, samples.length);
  const frame = samples.slice(0, frameSize);
  let bestCorrelation = -1;
  let bestPeriod = minPeriod;
  for (let period = minPeriod; period <= Math.min(maxPeriod, frameSize / 2); period++) {
    let correlation = 0;
    let energy1 = 0;
    let energy2 = 0;
    const len = Math.min(frameSize - period, 2048);
    for (let i = 0; i < len; i++) {
      correlation += frame[i] * frame[i + period];
      energy1 += frame[i] * frame[i];
      energy2 += frame[i + period] * frame[i + period];
    }
    const normalizer = Math.sqrt(energy1 * energy2);
    if (normalizer > 0) {
      correlation /= normalizer;
    }
    if (correlation > bestCorrelation) {
      bestCorrelation = correlation;
      bestPeriod = period;
    }
  }
  const fundamentalFrequency = sampleRate / bestPeriod;
  const confidence = Math.max(0, Math.min(1, bestCorrelation));
  const estimatedGender = fundamentalFrequency < 180 ? "male" : "female";
  return { estimatedGender, fundamentalFrequency, confidence };
}
function selectVoiceForGender(gender) {
  if (gender === "male") {
    return MALE_VOICES[Math.floor(Math.random() * MALE_VOICES.length)];
  }
  return FEMALE_VOICES[Math.floor(Math.random() * FEMALE_VOICES.length)];
}
async function detectVoice(req, res) {
  try {
    const { audio: audio2 } = req.body;
    if (!audio2) {
      return res.status(400).json({ error: "Missing required field: audio (base64 encoded)" });
    }
    const audioBuffer = Buffer.from(audio2, "base64");
    const wavHeader = createWavHeader(audioBuffer.length, 16e3, 16, 1);
    const wavBuffer = Buffer.concat([wavHeader, audioBuffer]);
    const pitchAnalysis = analyzeAudioPitch(wavBuffer);
    const suggestedVoiceId = selectVoiceForGender(pitchAnalysis.estimatedGender);
    res.json({
      suggestedVoiceId,
      estimatedGender: pitchAnalysis.estimatedGender,
      fundamentalFrequency: Math.round(pitchAnalysis.fundamentalFrequency),
      confidence: Math.round(pitchAnalysis.confidence * 100) / 100,
      maleVoices: MALE_VOICES,
      femaleVoices: FEMALE_VOICES
    });
  } catch (error) {
    console.error("Voice detection error:", error);
    res.status(500).json({ error: "Voice detection failed" });
  }
}
async function translate(req, res) {
  try {
    const { audio: audio2, sourceLanguage, targetLanguage, detectEmotion: detectEmotion3, includeAudio = true, voiceId } = req.body;
    if (!audio2 || !sourceLanguage || !targetLanguage) {
      res.status(400).json({ error: "Missing required fields: audio, sourceLanguage, targetLanguage" });
      return;
    }
    const pipelineStart = Date.now();
    const audioBuffer = Buffer.from(audio2, "base64");
    const wavHeader = createWavHeader(audioBuffer.length, 16e3, 16, 1);
    const wavBuffer = Buffer.concat([wavHeader, audioBuffer]);
    const preferLocal = process.env.PREFER_LOCAL_AI === "true";
    if (preferLocal) {
      try {
        const { isLocalAIAvailable: isLocalAIAvailable2, localTranslateSpeech: localTranslateSpeech2 } = await Promise.resolve().then(() => (init_local_ai_service(), local_ai_service_exports));
        const availability = await isLocalAIAvailable2();
        if (availability.whisper && availability.translation) {
          const result = await localTranslateSpeech2(
            wavBuffer,
            sourceLanguage,
            targetLanguage,
            detectEmotion3
          );
          let audioBase642 = null;
          let usedVoice = "alloy";
          if (includeAudio && result.translatedText) {
            try {
              const validVoiceId = voiceId && VALID_VOICE_IDS.includes(voiceId) ? voiceId : null;
              if (validVoiceId) {
                usedVoice = validVoiceId;
              } else {
                const voiceConfig = EMOTION_VOICE_MAP[result.emotion || "neutral"] || EMOTION_VOICE_MAP.neutral;
                usedVoice = voiceConfig.voice;
              }
              const { textToSpeech: textToSpeech4 } = await Promise.resolve().then(() => (init_client2(), client_exports));
              const ttsBuffer = await textToSpeech4(result.translatedText, usedVoice, "mp3", targetLanguage);
              audioBase642 = ttsBuffer.toString("base64");
            } catch (ttsErr) {
              console.warn("[Translation] TTS failed for local result:", ttsErr);
            }
          }
          res.json({
            originalText: result.originalText,
            translatedText: result.translatedText,
            emotion: result.emotion || null,
            audioBase64: audioBase642,
            voiceId: usedVoice,
            sourceLanguage,
            targetLanguage,
            latencyMs: Date.now() - pipelineStart,
            provider: "local"
          });
          return;
        }
      } catch (localError) {
        console.warn("[Translation] Local AI unavailable, falling back to OpenAI");
      }
    }
    const { speechToText: speechToText3, textToSpeech: textToSpeech3, openai: openai7 } = await Promise.resolve().then(() => (init_client2(), client_exports));
    let transcribedText = "";
    try {
      transcribedText = await speechToText3(wavBuffer, "wav", sourceLanguage);
    } catch (sttError) {
      console.warn("[Translation] STT failed (possibly bad audio):", sttError?.message || sttError);
      res.json({ originalText: "", translatedText: "", emotion: null, audioBase64: null });
      return;
    }
    if (!transcribedText || transcribedText.trim().length === 0) {
      res.json({ originalText: "", translatedText: "", emotion: null, audioBase64: null });
      return;
    }
    let translatedText = transcribedText;
    try {
      const { getCachedTranslation: getCachedTranslation4, setCachedTranslation: setCachedTranslation3 } = await Promise.resolve().then(() => (init_ultra_pipeline(), ultra_pipeline_exports));
      const cached = getCachedTranslation4(transcribedText, sourceLanguage, targetLanguage);
      if (cached) {
        translatedText = cached;
      } else {
        try {
          const response = await openai7.chat.completions.create({
            model: "gpt-4o-mini",
            messages: [
              { role: "system", content: "You are a fast translator. Output only the translation, nothing else." },
              { role: "user", content: `Translate from ${sourceLanguage} to ${targetLanguage}:

${transcribedText}` }
            ],
            max_tokens: 300,
            temperature: 0.3
          });
          translatedText = response.choices[0]?.message?.content?.trim() || transcribedText;
          if (translatedText && translatedText !== transcribedText) {
            setCachedTranslation3(transcribedText, sourceLanguage, targetLanguage, translatedText);
          }
        } catch {
          try {
            const url = `https://api.mymemory.translated.net/get?q=${encodeURIComponent(transcribedText)}&langpair=${sourceLanguage}|${targetLanguage}`;
            const ctrl = new AbortController();
            const t = setTimeout(() => ctrl.abort(), 2e3);
            const resp = await fetch(url, { signal: ctrl.signal });
            clearTimeout(t);
            if (resp.ok) {
              const data = await resp.json();
              if (data.responseStatus === 200 && data.responseData?.translatedText) {
                translatedText = data.responseData.translatedText;
              }
            }
          } catch {
          }
        }
      }
    } catch {
      translatedText = transcribedText;
    }
    let emotion = null;
    if (detectEmotion3) {
      const text2 = transcribedText.toLowerCase();
      if (/\b(happy|glad|great|wonderful|love|yay|haha|😊|😄)\b/i.test(text2)) emotion = "happy";
      else if (/\b(sad|sorry|miss|cry|😢|😞)\b/i.test(text2)) emotion = "sad";
      else if (/\b(angry|mad|furious|hate|damn|😡)\b/i.test(text2)) emotion = "angry";
      else if (/\b(excited|amazing|wow|awesome|incredible|🎉)\b/i.test(text2)) emotion = "excited";
      else if (/\b(calm|peaceful|relax|gentle)\b/i.test(text2)) emotion = "calm";
      else if (/\b(stressed|anxious|worried|nervous)\b/i.test(text2)) emotion = "stressed";
      else emotion = "neutral";
    }
    let audioBase64 = null;
    let usedVoiceId = "alloy";
    if (includeAudio && translatedText && translatedText.trim().length > 0) {
      try {
        const validVoiceId = voiceId && VALID_VOICE_IDS.includes(voiceId) ? voiceId : null;
        if (validVoiceId) {
          usedVoiceId = validVoiceId;
        } else {
          const voiceConfig = EMOTION_VOICE_MAP[emotion || "neutral"] || EMOTION_VOICE_MAP.neutral;
          usedVoiceId = voiceConfig.voice;
        }
        let emotionModulatedText = translatedText.trim();
        const emotionSpeed = EMOTION_SPEED_MAP[emotion || "neutral"] || 1;
        if (emotion && emotion !== "neutral") {
          const intensity = emotionSpeed;
          if (emotion === "sad" && intensity < 1) {
            emotionModulatedText = emotionModulatedText.replace(/\./g, "...");
          } else if (emotion === "angry" && intensity > 1) {
            emotionModulatedText = emotionModulatedText.replace(/\./g, "!");
          }
        }
        const ttsBuffer = await textToSpeech3(
          emotionModulatedText,
          usedVoiceId,
          "mp3",
          targetLanguage
        );
        audioBase64 = ttsBuffer.toString("base64");
      } catch (ttsError) {
        console.warn("[Translation] Voice identity TTS failed:", ttsError);
      }
    }
    res.json({
      originalText: transcribedText,
      translatedText: translatedText.trim(),
      emotion,
      audioBase64,
      voiceId: usedVoiceId,
      sourceLanguage,
      targetLanguage,
      latencyMs: Date.now() - pipelineStart,
      provider: "openai"
    });
  } catch (error) {
    console.error("Call translation error:", error);
    res.status(500).json({ error: "Translation failed" });
  }
}
